# Set your OpenAI API key
openai.api_key = os.getenv('OPENAI_API_KEY')


def generate_similar_questions(question, num_questions=5):
    response = openai.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            # {"role": "system", "content": "You are an assistant that rephrases questions to create similar ones without changing their meaning and using the same language of the questions."},
            # {"role": "user", "content": f"Generate {num_questions} different ways to ask the following question without numbering or bullet points:\n\n\"{question}\""}
            {"role": "system", "content": "Sei un assistente che riformula le domande per crearne di simili senza cambiarne il significato e risponde sempre in italiano."},
            {"role": "user", "content": f"Crea {
                num_questions} diverse formulazioni per la seguente domanda senza numeri o elenchi puntati: \n\n{question}"}
        ],
        temperature=0.7,
        max_tokens=600,
        n=1,
    )
    # Extract the assistant's reply
    assistant_reply = response.choices[0].message.content.strip()

    # Remove numbering or bullet points using regex
    similar_questions = []
    for line in assistant_reply.split('\n'):
        line = line.strip()
        # Remove any leading numbers, dots, or bullet points
        line = re.sub(r'^[\d\.\-\•\s]+', '', line)
        if line:
            similar_questions.append(line)
    return similar_questions


# List to store the augmented dataset
augmented_dataset = []

# Initialize the filename for saving the dataset
now = datetime.now()
datetime_string = now.strftime('%Y%m%d_%H%M%S')  # Format: YYYYMMDD_HHMMSS
filename = f'augmented_dataset_{datetime_string}.json'

for item in tqdm(original_questions, desc='Processing questions'):
    question = item["question"]
    answer = item["answer"]
    try:
        similar_questions = []
        total_questions_needed = NUM_SIMILAR_QUESTIONS
        max_batch_size = 20
        pbar_desc = f"Generating similar questions for: '{question}'"

        with tqdm(total=total_questions_needed, desc=pbar_desc) as pbar:
            while len(similar_questions) < total_questions_needed:
                batch_size = min(
                    max_batch_size, total_questions_needed - len(similar_questions))
                new_questions = generate_similar_questions(
                    question=question, num_questions=batch_size)
                # Remove duplicates
                new_questions = [
                    q for q in new_questions if q not in similar_questions]
                similar_questions.extend(new_questions)
                pbar.update(len(new_questions))

                # If no new questions are generated (to prevent infinite loop)
                if not new_questions:
                    print(
                        f"Could not generate more unique questions for: '{question}'")
                    break

        # Trim the list to the desired number of questions
        similar_questions = similar_questions[:NUM_SIMILAR_QUESTIONS]

        augmented_dataset.append({
            "question": question,
            "answer": answer,
            "similar_questions": similar_questions
        })

        # Save the augmented dataset to the JSON file after each question
        with open(filename, 'w', encoding='utf-8') as f:
            json.dump(augmented_dataset, f, ensure_ascii=False, indent=4)

        print(f"Original Question: {question}")
        print(f"Expected Answer: {answer}")
        print("Generated Similar Questions:")
        for idx, q in enumerate(similar_questions, 1):
            print(f"{idx}. {q}")
        print("\n")
    except Exception as e:
        print(f"An error occurred while processing the question: {question}")
        print(f"Error: {e}\n")
